import org.lwjgl.system.MemoryStack;
import org.lwjgl.util.lmdb.LMDB;
import org.lwjgl.util.lmdb.MDBStat;
import org.lwjgl.util.lmdb.MDBVal;
import org.mockito.MockedStatic;

/** An advisory batch forecast must not replace measured reserve and caller-owned recovery checks. */
@Isolated
class LmdbPersistentAlignedCapacityTest {
	@Test
	@Timeout(60)
	void aPhysicallyFittingBatchStillPreservesHardReserveBeforeCallbacks(@TempDir Path directory) throws Exception {
		int rows = 2_000;
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setTripleDBSize(1L << 20)
				.setAutoGrow(true)
				.setForceSync(true)
				.setSketchEstimatorEnabled(false);
		long[] subjects = new long[rows];
		long[] predicates = new long[rows];
		long[] objects = new long[rows];
		long[] contexts = new long[rows];
		Arrays.fill(predicates, 20);
		Arrays.fill(objects, 99);
		Arrays.fill(contexts, 7);
		for (int row = 0; row < rows; row++) {
			subjects[row] = 10_000 + row;
		}
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.startTransaction();
			store.storeTriple(1, 2, 3, 0, true);
			store.commit();
			long map = store.mapSizeBytes();
			int pageSize;
			try (MemoryStack stack = MemoryStack.stackPush()) {
				MDBStat stat = MDBStat.malloc(stack);
				LmdbUtil.E(LMDB.mdb_env_stat(store.env, stat));
				pageSize = stat.ms_psize();
			}
			long revision = store.getDataRevision();
			assertThat(map).isEqualTo(1L << 20);
			TxnReplayPolicy.Decision admission = store.prepareReplayDecision();
			TxnReplayPolicy.Decision frozen = admission.forFrozenReplay();
			store.startTransaction(frozen);
			long writer = store.writeTxn;
			LmdbPersistentAdjacency authority = LmdbPersistentAdjacency.openExisting(writer);
			Map<Long, Integer> cursors = new HashMap<>();
			List<Integer> callbacks = new ArrayList<>();
			long[] writes = new long[2];
			long[] sampledBytes = new long[1];
			int[] depth = new int[1];
			try (MockedStatic<LMDB> ignored = mockStatic(LMDB.class, invocation -> {
				if (depth[0]++ != 0) {
					try {
						return invocation.callRealMethod();
					} finally {
						depth[0]--;
					}
				}
				try {
					String method = invocation.getMethod().getName();
					if (method.equals("mdb_cursor_open")) {
						Object result = invocation.callRealMethod();
						if ((int) result == MDB_SUCCESS && (long) invocation.getArgument(0) == writer) {
							PointerBuffer handle = invocation.getArgument(2);
							assertThat(cursors.put(handle.get(0), invocation.getArgument(1))).isNull();
						}
						return result;
					}
					if (method.equals("mdb_cursor_close")) {
						Object result = invocation.callRealMethod();
						cursors.remove((long) invocation.getArgument(0));
						return result;
					}
					if (method.equals("mdb_put") && (long) invocation.getArgument(0) == writer
							&& (int) invocation.getArgument(1) == authority.deltasDbi()) {
						Object result = invocation.callRealMethod();
						if ((int) result == MDB_SUCCESS) {
							writes[0]++;
						}
						return result;
					}
					if (method.equals("mdb_cursor_put")
							&& Integer.valueOf(authority.metadataDbi())
									.equals(cursors.get((long) invocation.getArgument(0)))) {
						MDBVal key = invocation.getArgument(1);
						boolean context = key.mv_size() == 9
								&& key.mv_data().get(0) == LmdbPersistentAdjacency.CONTEXT_TOTAL_PREFIX;
						Object result = invocation.callRealMethod();
						if ((int) result == MDB_SUCCESS && context) {
							writes[1]++;
							sampledBytes[0] = LmdbUtil.getNewSize(pageSize, writer, 0);
						}
						return result;
					}
					if (method.equals("mdb_txn_abort") && (long) invocation.getArgument(0) == writer) {
						assertThat(cursors).as("all batch cursors close before caller-owned abort").isEmpty();
					}
					return invocation.callRealMethod();
				} finally {
					depth[0]--;
				}
			})) {
				FrozenStatementCapacityException failure = assertThrows(FrozenStatementCapacityException.class,
						() -> store.storeTriplesAligned(subjects, predicates, objects, contexts, rows, true, row -> {
							assertThat(cursors).as("callbacks cannot retain native mutation cursors").isEmpty();
							callbacks.add(row);
						}));
				assertThat(store.ownsFrozenCapacity(failure, frozen)).isTrue();
				assertThat(store.ownsFrozenCapacity(failure, admission.forFrozenReplay())).isFalse();
				assertThat(cursors).isEmpty();
				if (store.writeTxn != 0) {
					sampledBytes[0] = LmdbUtil.getNewSize(pageSize, store.writeTxn, 0);
				}
				store.rollback();
			}
			System.out.printf("aligned-reserve rows=%d deltaPuts=%d contextPuts=%d sampledBytes=%d map=%d%n",
					rows, writes[0], writes[1], sampledBytes[0], map);
			assertThat(writes[0]).as("both directions actually fit before the reserve-only refusal")
					.isEqualTo(2L * rows);
			assertThat(writes[1]).isEqualTo(rows);
			assertThat(sampledBytes[0]).isGreaterThan(map - LmdbUtil.MIN_FREE_SPACE).isLessThan(map);
			assertThat(callbacks).isEmpty();
			assertThat(store.mapSizeBytes()).isEqualTo(map);
			assertThat(store.getDataRevision()).isEqualTo(revision);
			assertThat(store.writeTxn).isZero();
			try (var txn = store.getTxnManager().createReadTxn();
					var result = store.getTriples(txn, -1, -1, -1, -1, true)) {
				assertThat(result.next()).containsExactly(1, 2, 3, 0);
				assertThat(result.next()).isNull();
			}
		}
		try (TripleStore reopened = new TripleStore(directory.toFile(), config, null);
				var txn = reopened.getTxnManager().createReadTxn();
				var result = reopened.getTriples(txn, -1, -1, -1, -1, true)) {
			assertThat(result.next()).containsExactly(1, 2, 3, 0);
			assertThat(result.next()).isNull();
		}
	}
}
